mapper.select:
with search_query as ( select plainto_tsquery('public.zhparser_cfg', #{keyword}) as value ) select a.id, a.title, a.summary, a.cover_url, a.is_top, a.published_at, a.view_count, a.comment_count, a.category_id, case when to_tsvector('public.zhparser_cfg', a.title) @@ search_query.value then ts_headline( 'public.zhparser_cfg', a.title, search_query.value, 'StartSel=__BLOG_SEARCH_HIGHLIGHT_START__, StopSel=__BLOG_SEARCH_HIGHLIGHT_END__, HighlightAll=true' ) end as highlighted_title, case when to_tsvector('public.zhparser_cfg', a.summary) @@ search_query.value then ts_headline( 'public.zhparser_cfg', a.summary, search_query.value, 'StartSel=__BLOG_SEARCH_HIGHLIGHT_START__, StopSel=__BLOG_SEARCH_HIGHLIGHT_END__, HighlightAll=true' ) when to_tsvector('public.zhparser_cfg', a.content_text) @@ search_query.value then ts_headline( 'public.zhparser_cfg', a.content_text, search_query.value, 'StartSel=__BLOG_SEARCH_HIGHLIGHT_START__, StopSel=__BLOG_SEARCH_HIGHLIGHT_END__, MinWords=10, MaxWords=35, ShortWord=1, MaxFragments=1' ) end as search_snippet from blog_article a cross join search_query where a.status = 'PUBLISHED' and a.category_id in
#{categoryId}
and ( a.search_vector @@ search_query.value or ( ( (numnode(search_query.value) = 0 and char_length(#{keyword}) = 1) or #{keyword} ~ '^[0-9]+$' ) and ( strpos(lower(coalesce(a.title, '')), lower(#{keyword})) > 0 or strpos(lower(coalesce(a.summary, '')), lower(#{keyword})) > 0 or strpos(lower(coalesce(a.content_text, '')), lower(#{keyword})) > 0 ) ) )
and a.id in
#{articleId}
and a.is_top = #{isTop}
order by
case when numnode(search_query.value) > 0 then ts_rank(a.search_vector, search_query.value) else 0 end desc,
a.is_top desc,
a.published_at desc, a.id desc
